nextflow_process {

    name "Test Process PURGEDUPS_GETSEQS"

    script "../main.nf"
    process "PURGEDUPS_GETSEQS"

    tag "modules"
    tag "modules_nfcore"
    tag "purgedups"
    tag "purgedups/getseqs"

    config './nextflow.config'

    test("sarcov2 - fasta - bed - e option") {

        when {

            params {
                get_seqs_args = null
            }

            process {
                """
                ch_bed = channel.of('MT192765.1\\t1\\t10000\\tJUNK\\n').collectFile(name: 'test.bed' )
                input[0] = channel.of([
                    [ id:'test'],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]).combine(ch_bed)
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }

    test("sarcov2 - fasta - bed - no e option") {


        when {

            params {
                get_seqs_args = ""
            }

            process {
                """
                ch_bed = channel.of('MT192765.1\\t1\\t10000\\tJUNK\\n').collectFile(name: 'test.bed' )
                input[0] = channel.of([
                    [ id:'test'],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]).combine(ch_bed)
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }

    test("sarcov2 - fasta - bed - explicit args set") {

        when {

            params {
                get_seqs_args = "-es -l 1000"
            }

            process {
                """
                ch_bed = channel.of('MT192765.1\\t1\\t10000\\tJUNK\\n').collectFile(name: 'test.bed' )
                input[0] = channel.of([
                    [ id:'test'],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]).combine(ch_bed)
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }

    test("sarcov2 - fasta - bed -- stub") {

        options "-stub"

        when {

            params {
                get_seqs_args = null
            }

            process {
                """
                ch_bed = channel.of('MT192765.1\\t1\\t10000\\tJUNK\\n').collectFile(name: 'test.bed' )
                input[0] = channel.of([
                    [ id:'test'],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]).combine(ch_bed)
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }
}

